#include "Monstey_LogicalMapsFixture.hpp"
namespace {
struct Monstey_Stop:std::runtime_error{Monstey_Stop():std::runtime_error("explicit allocator stop") {}};
void Monstey_Fault(const std::function<void()>&call,std::uint32_t at,unsigned width,bool writing){bool hit=false;try{call();}catch(const Monstey::Monstey_FearDbFault&e){hit=true;Monstey_Check(e.address==at&&e.width==width&&e.writing==writing,"exact owned fault operand");}Monstey_Check(hit,"owned fault expected");++Monstey_cases;}
void Monstey_Publication(){
 {Monstey_Fixture f;f.maps.allocate={};f.mem.bytes={};bool hit=false;try{f.maps.Initialize(f.mem,0xFFFFFFFF,true);}catch(const Monstey::Monstey_FearUnpackedCallbackBoundaryFault&e){hit=true;Monstey_Check(e.native_site==0,"logical missing allocator site");}Monstey_Check(hit,"missing allocator precedes all memory");++Monstey_cases;}
 {Monstey_Fixture f;const auto bad=f.base+static_cast<std::uint32_t>(f.image.size())-8u;Monstey_Fault([&]{f.maps.Initialize(f.mem,bad,false);},bad+8,4,true);const auto h=f.R(bad+4);Monstey_Check(f.R(h)==h&&f.R(h+4)==h&&f.R(h+8)==h,"head initialized before count fault");Monstey_Check(f.R(h+0x35,1)==1,"nil before map count fault");}
 for(bool parsed:{false,true}){Monstey_Fixture f;const auto head=f.Init(parsed);f.Input("key",{0x87654321,0xAA,0xCC,"value"});const auto before=f.image;unsigned calls=0;f.maps.allocate=[&,state=0u](Monstey_Memory,std::uint32_t)mutable->std::uint32_t{Monstey_Check(++state==++calls,"stateful throwing allocator target");throw Monstey_Stop();};for(unsigned i=0;i<2;++i){bool hit=false;try{if(parsed)f.maps.InsertParsed(f.mem,f.map,f.hidden,0,f.pair);else f.maps.PutConstraint(f.mem,f.map,f.pair,1,2,3);}catch(const Monstey_Stop&){hit=true;}Monstey_Check(hit&&f.image==before,"allocation exception no stores");++Monstey_cases;}Monstey_Check(f.R(head+4)==head&&f.R(f.map+8)==0,"allocation exception unpublishes");}
 {Monstey_Fixture f;const auto head=f.Init(true);f.Input(std::string(16,'K'),{17,2,3,"v"});f.maps.strings.allocate={};bool hit=false;try{f.maps.InsertParsed(f.mem,f.map,f.hidden,0,f.pair);}catch(const Monstey::Monstey_FearUnpackedBoundaryFault&){hit=true;}Monstey_Check(hit,"long key allocator boundary");const auto n=f.allocations.back().first;Monstey_Check(f.R(n)==head&&f.R(n+4)==head&&f.R(n+8)==head,"unpublished node links initialized");Monstey_Check(f.R(n+0x4C,1)==0&&f.R(n+0x4D,1)==0,"unpublished node flags");Monstey_Check(f.R(n+12)==0xA5A5A5A5,"key not stored after missing allocation");Monstey_Check(f.R(head+4)==head&&f.R(f.map+8)==0,"key failure retains empty tree");++Monstey_cases;}
 {Monstey_Fixture f;const auto head=f.Init(true);f.Input("key",{0xFEDCBA98,2,3,std::string(16,'V')});f.maps.strings.allocate={};bool hit=false;try{f.maps.InsertParsed(f.mem,f.map,f.hidden,0,f.pair);}catch(const Monstey::Monstey_FearUnpackedBoundaryFault&){hit=true;}const auto n=f.allocations.back().first;Monstey_Check(hit&&f.S(n+12)=="key"&&f.R(n+40)==0xFEDCBA98,"key/type precede value allocation failure");Monstey_Check(f.R(n+72)==0xA5A5A5A5&&f.R(head+4)==head&&f.R(f.map+8)==0,"value failure no opaque/publication");++Monstey_cases;}
 {Monstey_Fixture f;f.Init(true);Monstey_Value v{0xABCDEF01,2,0x98765432,"v"};f.Input("key",v);const auto bad=f.base+static_cast<std::uint32_t>(f.image.size());Monstey_Fault([&]{f.maps.InsertParsed(f.mem,f.map,bad,0,f.pair);},bad,4,true);Monstey_Oracle o;o.emplace("key",v);f.Verify(true,o);}
}
void Monstey_ConsumedEpochs(){
 {Monstey_Fixture f;f.Init(true);f.Input("old",{1,2,3,"oldvalue"});unsigned nodes=0;f.maps.allocate=[&](Monstey_Memory,std::uint32_t n){++nodes;Monstey_Check(n==80,"epoch node width");f.S(f.pair,"new",f.base+0x300000);f.W(f.pair+28,0xFFFFFFFF);return f.base+0xA000;};f.maps.InsertParsed(f.mem,f.map,f.hidden,0,f.pair);Monstey_Oracle o;o.emplace("new",Monstey_Value{0xFFFFFFFF,2,3,"oldvalue"});f.Verify(true,o);Monstey_Check(nodes==1,"one node allocation");++Monstey_cases;}
 {Monstey_Fixture f;f.Init(true);const auto key=std::string(17,'K'),value=std::string(21,'V');f.Input(key,{0x10,2,0x30,value});unsigned calls=0;f.maps.strings.allocate=[&,cursor=f.base+0xB000u](Monstey_Memory,std::uint32_t n)mutable{++calls;const auto p=cursor;cursor+=n+16;if(calls==1){f.W(f.pair+28,0xFACEB00C);f.W(f.pair+60,0xDEAD2222);}if(calls==2)f.W(f.pair+60,0xFEED3333);return p;};f.maps.InsertParsed(f.mem,f.map,f.hidden,0,f.pair);Monstey_Oracle o;o.emplace(key,Monstey_Value{0xFACEB00C,2,0xFEED3333,value});f.Verify(true,o);Monstey_Check(calls==2,"persistent string allocator target");++Monstey_cases;}
 {Monstey_Fixture f;f.Init(true);f.Input("same",{0x10,2,0x30,"initial"});f.maps.InsertParsed(f.mem,f.map,f.hidden,0,f.pair);const auto n=f.R(f.hidden);const auto before=f.allocations.size();f.Input("same",{0x99,8,9,"replacement"});f.W(f.pair+32+20,0xFFFFFFFF);f.W(f.pair+32+24,0xFFFFFFFF);f.W(f.pair+32+4,0xFFFFFFFF);f.maps.allocate={};f.maps.strings.allocate={};const auto out=f.maps.InsertParsed(f.mem,f.map,f.hidden,0xFFFFFFFF,f.pair);Monstey_Check(out==f.hidden&&f.R(f.hidden)==n&&f.allocations.size()==before,"duplicate no allocation");Monstey_Oracle o;o.emplace("same",Monstey_Value{0x10,2,0x30,"initial"});f.Verify(true,o);++Monstey_cases;}
 {Monstey_Fixture f;f.Init(false);f.S(f.pair,"same",0);f.maps.PutConstraint(f.mem,f.map,f.pair,1,2,3);const auto n=f.R(f.R(f.map+4)+4);f.maps.allocate={};f.maps.strings.allocate={};f.maps.PutConstraint(f.mem,f.map,f.pair,0xFFFFFFFF,0x80000000,0xFEDCBA98);Monstey_Check(f.R(f.R(f.map+4)+4)==n,"constraint duplicate identity");Monstey_Oracle o;o.emplace("same",Monstey_Value{0xFFFFFFFF,0x80000000,0xFEDCBA98,{}});f.Verify(false,o);++Monstey_cases;}
}
void Monstey_ResultAliases(){
 {Monstey_Fixture f;f.Init(true);f.Input("key",{3,0,0x55667788,"value"});const auto node=f.base+0xA000;f.maps.allocate=[=](Monstey_Memory,std::uint32_t){return node;};const auto result=f.maps.InsertParsed(f.mem,f.map,node+40,0,f.pair);Monstey_Check(result==node+40&&f.R(node+40)==node,"hidden result overwrites type after publish");Monstey_Oracle o;o.emplace("key",Monstey_Value{node,0,0x55667788,"value"});f.Verify(true,o);++Monstey_cases;}
 {Monstey_Fixture f;const auto head=f.Init(true);f.Input("key",{3,0,0x55667788,"value"});const auto out=f.maps.InsertParsed(f.mem,f.map,f.map+8,0,f.pair);const auto node=f.R(head+4);Monstey_Check(out==f.map+8&&f.R(f.map+8)==node,"hidden result live map-count alias");Monstey_Check(f.S(node+12)=="key"&&f.R(head)==node&&f.R(head+8)==node,"published before hidden count overwrite");++Monstey_cases;}
}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("report argument required");Monstey_Publication();Monstey_ConsumedEpochs();Monstey_ResultAliases();std::ofstream out(argv[1]);out<<"{\"status\":\"PASS\",\"groups\":3,\"cases\":"<<Monstey_cases<<",\"checks\":"<<Monstey_checks<<"}\n";std::cout<<"PASS "<<Monstey_cases<<" cases "<<Monstey_checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
